// План specs/admin-coupons.md 2.5 (кейс CP-10). Admin, десктоп. @prod-safe: только чтение ответа rpc admin_list_coupons.
import { test, expect } from '../../fixtures';
import { blockCouponWrites, expectNoCouponWrites, openCoupons, restoreTest, startInTest } from './coupon-helpers';

test('Coupons API: admin_list_coupons returns stripe_coupon_id and sync_error for every coupon; QA- coupons are synced (Stripe id set, no sync error) #a10206 @desktop @prod-safe', async ({ asUser }) => {
  const page = await asUser('admin');
  await startInTest(page);
  const writes = await blockCouponWrites(page);
  try {
    const listResp = page.waitForResponse((r) => /\/rpc\/admin_list_coupons/.test(r.url()) && r.request().method() !== 'OPTIONS', { timeout: 30_000 });
    await openCoupons(page);
    const resp = await listResp;
    expect(resp.ok(), 'admin_list_coupons отвечает 2xx').toBeTruthy();
    const json = await resp.json();
    const list: Record<string, unknown>[] = Array.isArray(json) ? json : (json?.coupons ?? json?.data ?? []);
    expect(list.length, 'купоны в ответе').toBeGreaterThan(0);
    // Источник: AC2 #a10206 — купон создаётся и в Stripe; сбой синхронизации виден (sync_error). Ручная проверка 18.10.
    for (const c of list) {
      expect(c, `купон ${String(c.code)}: поле stripe_coupon_id`).toHaveProperty('stripe_coupon_id');
      expect(c, `купон ${String(c.code)}: поле sync_error`).toHaveProperty('sync_error');
    }
    const qa = list.filter((c) => /^QA-/.test(String(c.code ?? '')));
    expect(qa.length, 'QA-купоны в ответе').toBeGreaterThan(0);
    for (const c of qa) {
      expect(c.stripe_coupon_id, `${String(c.code)}: есть Stripe id`).toBeTruthy();
      expect(c.sync_error ?? null, `${String(c.code)}: нет ошибки синхронизации`).toBeNull();
    }
  } finally {
    await restoreTest(page);
  }
  expectNoCouponWrites(writes);
});
